def test_bit_ops_unequal_offsets():
    a = Tibs('0b11001010_01110100_10111100')
    b = Tibs('0b10110101_11001001_00101110')
    left = a[3:21]
    right = b[5:23]

    expected_or = [x or y for x, y in zip(left, right)]
    expected_and = [x and y for x, y in zip(left, right)]
    expected_xor = [x != y for x, y in zip(left, right)]

    assert list(left | right) == expected_or
    assert list(left & right) == expected_and
    assert list(left ^ right) == expected_xor


class TestAdditionalCoverage:
    def test_tibs_set_unset_and_inverted_return_new_instances(self):
        t = Tibs("0b10110010")

        assert t.set_at(range(1, 8, 2)) == Tibs("0b11110111")
        assert Tibs("0b11111111").unset_at([-1, -3, 0]) == Tibs("0b01111010")
        assert Tibs("0b10000001").inverted(range(1, 7)) == Tibs("0b11111111")
        assert t == Tibs("0b10110010")

    def test_reverse_iterators_have_obvious_order_and_limits(self):
        t = Tibs("0b1010110010")

        assert list(t.rfind_all_iter("0b10")) == [8, 5, 2, 0]
        assert [chunk.bin for chunk in t.rchunks_iter(3)] == ["010", "110", "010", "1"]
        assert [chunk.bin for chunk in t.rchunks_iter(3, count=2)] == ["010", "110"]

    def test_tibs_byte_swapped_slice_returns_new_instance(self):
        t = Tibs("0x001122334455")

        assert t.byte_swapped(start=8, end=40) == Tibs("0x004433221155")
        assert t.byte_swapped(2, start=8, end=40) == Tibs("0x002211443355")
        assert t == Tibs("0x001122334455")

    def test_to_raw_data_reports_offset_and_length_for_unaligned_slice(self):
        t = Tibs("0x123456")[4:20]

        raw_bytes, offset, length = t.to_raw_data()

        assert raw_bytes == b"\x12\x34\x56"
        assert offset == 4
        assert length == 16
        assert t == Tibs("0x2345")

    def test_mutibs_append_pop_and_empty_pop_error(self):
        m = Mutibs("0b10")

        assert m.append(1) is None
        assert m == Tibs("0b101")
        assert m.pop() is True
        assert m.pop() is False
        assert m == Tibs("0b1")

        empty = Mutibs()
        with pytest.raises(IndexError):
            empty.pop()

    def test_mutibs_as_tibs_moves_data_out_and_empties_source(self):
        m = Mutibs("0x1234")

        moved = m.as_tibs()

        assert moved == Tibs("0x1234")
        assert m == Tibs()
        assert len(m) == 0

    def test_mutibs_as_raw_data_moves_data_out_and_empties_source(self):
        m = Mutibs("0x1234")

        assert m.as_raw_data() == (b"\x12\x34", 0, 16)
        assert m == Tibs()
        assert len(m) == 0

    def test_mutable_view_field_write_updates_underlying_source(self):
        m = Mutibs("0x0000")
        field = m.lsb0.le.field(15, 8)

        assert field.u == 0
        field.u = 0xab

        assert field.u == 0xab
        assert m == Mutibs("0x00ab")

    def test_shift_operators_zero_fill_and_keep_length(self):
        t = Tibs("0b1011")

        assert t << 2 == Tibs("0b1100")
        assert t >> 2 == Tibs("0b0010")
        assert t == Tibs("0b1011")

        m = Mutibs("0b1011")
        m <<= 2
        assert m == Tibs("0b1100")
        m >>= 2
        assert m == Tibs("0b0011")

    def test_reflected_add_and_multiply_accept_promotable_values(self):
        assert "0b11" + Tibs("0b00") == Tibs("0b1100")
        assert 3 * Tibs("0b10") == Tibs("0b101010")
        assert Mutibs("0b01") * 3 == Tibs("0b010101")

    def test_mutibs_decode_malformed_zstd_with_impossible_padding_raises_value_error(self):
        malformed = bytes.fromhex("110d28b52ffd240001000099e9d851")
        with pytest.raises(ValueError):
            Mutibs.decode(malformed)

    def test_bytes_apis_reject_integer_sequences(self):
        for cls in (Tibs, Mutibs):
            for value in ([0x61, 0x62], (0x61, 0x62)):
                with pytest.raises(TypeError):
                    cls.from_bytes(value)

        m = Mutibs("0x0000")
        for value in ([0x61, 0x62], (0x61, 0x62)):
            with pytest.raises(TypeError):
                m.write_bytes(value)
            with pytest.raises(TypeError):
                m.view().write_bytes(value)


class TestDtypeViewMutableViewEdgeCoverage:
    def test_dtype_spec_is_normalized_and_usable(self):
        d = Dtype("  U16_LE  ")

        assert repr(d) == "Dtype('u16_le')"
        assert d.kind is DtypeKind.Uint
        assert d.length == 16
        assert d.byte_order is ByteOrder.Little
        assert d.pack(0x1234) == Tibs("0x3412")
        assert d.unpack("0x3412") == 0x1234

    def test_dtype_from_params_accepts_none_byte_order_and_properties_are_read_only(self):
        d = Dtype.from_params(DtypeKind.Int, 8, None)

        assert repr(d) == "Dtype('i8')"
        assert d.byte_order is ByteOrder.Unspecified

        for name in ("kind", "length", "byte_order"):
            with pytest.raises(AttributeError):
                setattr(d, name, None)

    def test_dtype_unpack_methods_accept_negative_ranges_and_bytes_like_inputs(self):
        d = Dtype("u8")
        bits = Tibs.from_bytes(b"\x01\x02\x03\x04")

        assert d.unpack(bits, -24, -16) == 2
        assert d.unpack_values(bits, -24, -8) == [2, 3]
        assert list(d.unpack_values_iter(bits, -32, -8)) == [1, 2, 3]
        assert d.unpack_values(bytearray(b"\x05\x06")) == [5, 6]
        assert d.unpack_values(memoryview(b"\x07\x08")) == [7, 8]

    def test_dtype_pack_values_reports_late_item_overflow(self):
        with pytest.raises(OverflowError):
            Dtype("u4").pack_values([1, 2, 16])

    def test_dtype_bytes_pack_rejects_overlong_values(self):
        for value in (b"abc", bytearray(b"abc"), memoryview(b"abc")):
            with pytest.raises(ValueError):
                Dtype("bytes16").pack(value)
            with pytest.raises(ValueError):
                Tibs.from_value("bytes16", value)
            with pytest.raises(ValueError):
                Mutibs.from_value("bytes16", value)

    def test_dtype_bytes_pack_values_rejects_overlong_items(self):
        value_sets = [
            [b"ab", b"abc"],
            [bytearray(b"ab"), bytearray(b"abc")],
            [memoryview(b"ab"), memoryview(b"abc")],
        ]

        for values in value_sets:
            with pytest.raises(ValueError):
                Dtype("bytes16").pack_values(values)
            with pytest.raises(ValueError):
                Tibs.from_values("bytes16", values)
            with pytest.raises(ValueError):
                Mutibs.from_values("bytes16", values)

    def test_dtype_bytes_pack_rejects_integer_sequences(self):
        for value in ([0x61, 0x62], (0x61, 0x62)):
            with pytest.raises(TypeError):
                Dtype("bytes16").pack(value)
            with pytest.raises(TypeError):
                Tibs.from_value("bytes16", value)
            with pytest.raises(TypeError):
                Mutibs.from_value("bytes16", value)

    def test_dtype_float_specs_reject_unsupported_widths_at_construction(self):
        for length in (8, 24, 128):
            with pytest.raises(ValueError):
                Dtype(f"f{length}")
            with pytest.raises(ValueError):
                Dtype.from_params(DtypeKind.Float, length)

    def test_dtype_bytes_specs_reject_non_byte_widths_at_construction(self):
        for length in (1, 7, 9):
            with pytest.raises(ValueError):
                Dtype(f"bytes{length}")
            with pytest.raises(ValueError):
                Dtype.from_params(DtypeKind.Bytes, length)

    def test_dtype_text_specs_reject_non_digit_aligned_widths_at_construction(self):
        cases = [
            ("hex", DtypeKind.Hex, 7),
            ("oct", DtypeKind.Oct, 8),
        ]

        for prefix, kind, length in cases:
            with pytest.raises(ValueError):
                Dtype(f"{prefix}{length}")
            with pytest.raises(ValueError):
                Dtype.from_params(kind, length)

    def test_view_from_indices_empty_selection_is_empty_and_unusable_as_number(self):
        v = View.from_indices(Tibs("0xff"), [])

        assert len(v) == 0
        assert v.bin == ""
        assert v.to_tibs() == Tibs()
        assert v.to_mutibs() == Mutibs()

        with pytest.raises(ValueError):
            _ = v.u
        with pytest.raises(ValueError):
            v.field(0, 0)

    def test_view_from_indices_respects_layout_for_two_byte_selection(self):
        source = Tibs("0x1234")

        lsb0 = View.from_indices(source, range(16), bit_order=BitOrder.Lsb0)
        little = View.from_indices(source, range(16), byte_order=ByteOrder.Little)

        assert lsb0.hex == "3412"
        assert little.hex == "3412"
        assert lsb0.to_tibs() == little.to_tibs() == Tibs("0x3412")

    def test_view_non_byte_field_rejects_byte_oriented_reinterpretation(self):
        field = Tibs("0xff").field(0, 3)

        assert field.bin == "1111"
        with pytest.raises(ValueError):
            _ = field.le
        with pytest.raises(ValueError):
            _ = field.lsb0

    def test_mutable_view_empty_selection_allows_empty_write_only(self):
        m = Mutibs("0xff")
        v = MutableView.from_indices(m, [])

        assert len(v) == 0
        assert v.bin == ""
        assert v.write_bin("") is None
        assert m == Mutibs("0xff")

        with pytest.raises(ValueError):
            v.write_bin("1")

    def test_mutable_view_sparse_byte_write_updates_selected_source_bits(self):
        m = Mutibs("0x0000")
        v = MutableView.from_indices(m, [0, 2, 4, 6, 8, 10, 12, 14])

        assert v.bytes == b"\x00"
        v.bytes = b"\xff"

        assert v.bytes == b"\xff"
        assert m == Mutibs("0xaaaa")

    def test_mutable_view_revalidates_selected_indices_after_source_shrinks(self):
        m = Mutibs("0xff")
        v = MutableView.from_indices(m, [6, 7])

        assert v.bin == "11"
        del m[6:]

        with pytest.raises(ValueError):
            len(v)
        with pytest.raises(ValueError):
            _ = v.bin

    def test_mutable_view_signed_write_failure_leaves_source_unchanged(self):
        m = Mutibs.from_zeros(8)

        m.view().i = -1
        assert m == Mutibs("0xff")

        original = m.to_tibs()
        with pytest.raises(OverflowError):
            m.view().i = -129

        assert m == original

    def test_mutable_view_to_mutibs_materializes_copy(self):
        m = Mutibs("0x1234")

        copy = m.lsb0.to_mutibs()
        copy[0] = True

        assert copy == Mutibs("0xb412")
        assert m == Mutibs("0x1234")


# ---------------------------------------------------------------------------
# Property-based fuzz tests (hypothesis).
#
# Every generated Tibs/Mutibs is (optionally) built as a slice of a larger
# parent object, so the underlying storage often starts mid-byte. Operations
# are checked against a pure-Python list-of-bools / binary-string model.
# ---------------------------------------------------------------------------

from hypothesis import assume, given, settings
import hypothesis.strategies as st

FUZZ = settings(max_examples=75, deadline=None)


def _ref_bin(bits):
    return "".join("1" if b else "0" for b in bits)


def _normalize_strict_bounds(length, start, end):
    start = 0 if start is None else start
    end = length if end is None else end
    if start < 0:
        start += length
    if end < 0:
        end += length
    if not (0 <= start <= end <= length):
        raise ValueError
    return start, end


@st.composite
def bool_lists(draw, min_size=0, max_size=200):
    # Mix densities so low-entropy data stresses fallback search paths.
    # The bits come from one bulk byte draw rather than a draw per bit: drawing
    # each bit separately makes data generation cost far more than the tests.
    density = draw(st.sampled_from([2, 50, 98]))
    n = draw(st.integers(min_size, max_size))
    raw = draw(st.binary(min_size=n, max_size=n))
    # P(True) == density/100, and a byte of 0 is False so examples shrink
    # towards all-zero bits.
    threshold = 256 - round(density * 256 / 100)
    return [b >= threshold for b in raw]


@st.composite
def padded_tibs(draw, min_size=0, max_size=200):
    """A Tibs plus its reference bits, often stored at a bit offset."""
    bits = draw(bool_lists(min_size=min_size, max_size=max_size))
    pre = draw(bool_lists(max_size=13))
    post = draw(bool_lists(max_size=13))
    t = Tibs.from_bools(pre + bits + post)[len(pre):len(pre) + len(bits)]
    return t, bits


@st.composite
def padded_mutibs(draw, min_size=0, max_size=200):
    """A Mutibs plus its reference bits, often stored at a bit offset."""
    bits = draw(bool_lists(min_size=min_size, max_size=max_size))
    pre = draw(bool_lists(max_size=13))
    post = draw(bool_lists(max_size=13))
    m = Mutibs.from_bools(pre + bits + post)[len(pre):len(pre) + len(bits)]
    return m, bits


def _ref_occurrences(s, p):
    return [i for i in range(len(s) - len(p) + 1) if s.startswith(p, i)]


class TestFuzzSearch:
    @FUZZ
    @given(padded_tibs(min_size=1), st.data())
    def test_find_family_matches_string_reference(self, tb, data):
        t, bits = tb
        s = _ref_bin(bits)
        # Needle: usually a real substring (so matches exist), sometimes random.
        # Lengths deliberately straddle the 64-bit small/large search boundary.
        nlen = data.draw(st.integers(1, min(len(bits), 90)), label="needle_len")
        if data.draw(st.booleans(), label="from_haystack"):
            at = data.draw(st.integers(0, len(bits) - nlen), label="at")
            nbits = bits[at:at + nlen]
        else:
            nbits = data.draw(bool_lists(min_size=nlen, max_size=nlen))
        needle = Tibs.from_bools(nbits)
        p = _ref_bin(nbits)

        occurrences = _ref_occurrences(s, p)
        expected_find = occurrences[0] if occurrences else None
        expected_rfind = occurrences[-1] if occurrences else None

        assert t.find(needle) == expected_find
        assert t.rfind(needle) == expected_rfind
        assert t.find_all(needle) == occurrences
        assert list(t.find_all_iter(needle)) == occurrences
        assert list(t.rfind_all_iter(needle)) == occurrences[::-1]
        assert t.count(needle) == len(occurrences)

    @FUZZ
    @given(padded_tibs(min_size=1), st.data())
    def test_find_with_bounds_and_byte_alignment(self, tb, data):
        t, bits = tb
        s = _ref_bin(bits)
        nlen = data.draw(st.integers(1, min(len(bits), 70)), label="needle_len")
        at = data.draw(st.integers(0, len(bits) - nlen), label="at")
        nbits = bits[at:at + nlen]
        needle = Tibs.from_bools(nbits)
        p = _ref_bin(nbits)
        start = data.draw(st.integers(0, len(bits)), label="start")
        end = data.draw(st.integers(start, len(bits)), label="end")
        aligned = data.draw(st.booleans(), label="aligned")

        occurrences = [
            i for i in _ref_occurrences(s, p)
            if i >= start and i + nlen <= end and (not aligned or i % 8 == 0)
        ]
        assert t.find(needle, start, end, byte_aligned=aligned) == (
            occurrences[0] if occurrences else None
        )
        assert t.rfind(needle, start, end, byte_aligned=aligned) == (
            occurrences[-1] if occurrences else None
        )
        assert t.find_all(needle, start, end, byte_aligned=aligned) == occurrences

    @FUZZ
    @given(padded_tibs(min_size=1), st.data())
    def test_find_with_negative_bounds_matches_strict_reference(self, tb, data):
        t, bits = tb
        s = _ref_bin(bits)
        nlen = data.draw(st.integers(1, min(len(bits), 90)), label="needle_len")
        if data.draw(st.booleans(), label="from_haystack"):
            at = data.draw(st.integers(0, len(bits) - nlen), label="at")
            nbits = bits[at:at + nlen]
        else:
            nbits = data.draw(bool_lists(min_size=nlen, max_size=nlen), label="needle")
        needle = Tibs.from_bools(nbits)
        p = _ref_bin(nbits)
        start = data.draw(
            st.one_of(st.none(), st.integers(-len(bits) - 3, len(bits) + 3)),
            label="start",
        )
        end = data.draw(
            st.one_of(st.none(), st.integers(-len(bits) - 3, len(bits) + 3)),
            label="end",
        )
        aligned = data.draw(st.booleans(), label="byte_aligned")

        try:
            start_norm, end_norm = _normalize_strict_bounds(len(bits), start, end)
        except ValueError:
            with pytest.raises(ValueError):
                t.find(needle, start, end, byte_aligned=aligned)
            with pytest.raises(ValueError):
                t.rfind(needle, start, end, byte_aligned=aligned)
            with pytest.raises(ValueError):
                t.find_all(needle, start, end, byte_aligned=aligned)
            with pytest.raises(ValueError):
                list(t.find_all_iter(needle, start, end, byte_aligned=aligned))
            with pytest.raises(ValueError):
                list(t.rfind_all_iter(needle, start, end, byte_aligned=aligned))
            return

        occurrences = [
            i for i in range(start_norm, end_norm - nlen + 1)
            if (not aligned or i % 8 == 0) and s.startswith(p, i)
        ]
        assert t.find(needle, start, end, byte_aligned=aligned) == (
            occurrences[0] if occurrences else None
        )
        assert t.rfind(needle, start, end, byte_aligned=aligned) == (
            occurrences[-1] if occurrences else None
        )
        assert t.find_all(needle, start, end, byte_aligned=aligned) == occurrences
        assert list(t.find_all_iter(needle, start, end, byte_aligned=aligned)) == occurrences
        assert list(t.rfind_all_iter(needle, start, end, byte_aligned=aligned)) == (
            occurrences[::-1]
        )

    @FUZZ
    @given(padded_tibs(), st.data())
    def test_count_single_bit_with_bounds(self, tb, data):
        t, bits = tb
        start = data.draw(st.integers(0, len(bits)), label="start")
        end = data.draw(st.integers(start, len(bits)), label="end")
        assert t.count(1, start, end) == sum(bits[start:end])
        assert t.count(0, start, end) == (end - start) - sum(bits[start:end])

    @FUZZ
    @given(padded_tibs(), st.data())
    def test_count_single_bit_with_negative_bounds_matches_reference(self, tb, data):
        t, bits = tb
        start = data.draw(
            st.one_of(st.none(), st.integers(-len(bits) - 3, len(bits) + 3)),
            label="start",
        )
        end = data.draw(
            st.one_of(st.none(), st.integers(-len(bits) - 3, len(bits) + 3)),
            label="end",
        )

        try:
            start_norm, end_norm = _normalize_strict_bounds(len(bits), start, end)
        except ValueError:
            with pytest.raises(ValueError):
                t.count(1, start, end)
            with pytest.raises(ValueError):
                t.count(0, start, end)
            return

        selected = bits[start_norm:end_norm]
        assert t.count(1, start, end) == sum(selected)
        assert t.count(0, start, end) == len(selected) - sum(selected)

    @FUZZ
    @given(padded_tibs(min_size=1), st.data())
    def test_replaced_matches_string_reference(self, tb, data):
        t, bits = tb
        s = _ref_bin(bits)
        nlen = data.draw(st.integers(1, min(len(bits), 20)), label="old_len")
        at = data.draw(st.integers(0, len(bits) - nlen), label="at")
        old = bits[at:at + nlen]
        new = data.draw(bool_lists(max_size=12), label="new")

        # Left-to-right, non-overlapping replacement.
        out, i = [], 0
        while True:
            j = s.find(_ref_bin(old), i)
            if j == -1:
                out.append(s[i:])
                break
            out.append(s[i:j])
            out.append(_ref_bin(new))
            i = j + nlen
        expected = "".join(out)

        replaced = t.replaced(Tibs.from_bools(old), Tibs.from_bools(new))
        assert replaced.to_bin() == expected


class TestFuzzSlicingAndViews:
    @FUZZ
    @given(padded_tibs(), st.data())
    def test_step_slicing_matches_list(self, tb, data):
        t, bits = tb
        step = data.draw(st.sampled_from([-7, -3, -2, -1, 1, 2, 3, 7]), label="step")
        start = data.draw(st.one_of(st.none(), st.integers(-len(bits) - 2, len(bits) + 2)), label="start")
        stop = data.draw(st.one_of(st.none(), st.integers(-len(bits) - 2, len(bits) + 2)), label="stop")
        assert t[start:stop:step].to_bin() == _ref_bin(bits[start:stop:step])

