class TestFuzzFoundBugs:
    """Deterministic regressions for bugs found by the fuzz tests above.

    Repeating the same empty container in from_joined used to panic in Rust,
    as did passing empty ranges to the set/unset family of methods.
    """

    def test_from_joined_single_empty_item(self):
        # A single-element list containing an empty Tibs used to panic in
        # Rust ("Chunk width cannot be 0") via the repeated-list fast path.
        assert Tibs.from_joined([Tibs()]) == Tibs()
        empty = Tibs()
        assert Tibs.from_joined([empty, empty, empty]) == Tibs()

    def test_mutibs_from_joined_single_empty_item(self):
        assert Mutibs.from_joined([Mutibs()]) == Mutibs()

    def test_set_empty_ascending_range_is_noop(self):
        # range(1, 0) is empty in Python, so set() should change nothing.
        # It used to panic in Rust ("range 1..0 out of bounds").
        m = Mutibs.from_zeros(3)
        m.set(range(1, 0))
        assert m == Mutibs.from_zeros(3)

    def test_set_empty_descending_range_is_noop(self):
        # range(0, 2, -1) is empty in Python, so set() should change nothing.
        # It used to panic in Rust ("range 3..1 out of bounds").
        m = Mutibs.from_zeros(3)
        m.set(range(0, 2, -1))
        assert m == Mutibs.from_zeros(3)

    def test_unset_empty_descending_range_is_noop(self):
        # This used to raise IndexError ("End of slice out of bounds.")
        # even though the range contains no positions.
        m = Mutibs.from_ones(1)
        m.unset(range(0, 1, -1))
        assert m == Mutibs.from_ones(1)

    def test_set_at_empty_range_is_noop(self):
        # The non-mutating variants route through the same position handling.
        t = Tibs.from_zeros(3)
        assert t.set_at(range(1, 0)) == t
        assert t.unset_at(range(0, 2, -1)) == t

    def test_set_range_negative_values_match_list_semantics(self):
        # A range is interpreted exactly like the list of its contents, so
        # negative values index from the end just as they do in a list.
        m = Mutibs.from_zeros(4)
        m.set(range(-2, 3))  # [-2, -1, 0, 1, 2]
        assert m == Mutibs.from_bools([1, 1, 1, 1])

        m = Mutibs.from_zeros(4)
        m.set(range(-1, -3, -1))  # [-1, -2]
        assert m == Mutibs.from_bools([0, 0, 1, 1])

        m = Mutibs.from_zeros(4)
        m.set(range(3, -5, -1))  # [3, 2, 1, 0, -1, -2, -3, -4]
        assert m == Mutibs.from_ones(4)

        m = Mutibs.from_ones(4)
        m.unset(range(-1, -3, -1))
        assert m == Mutibs.from_bools([1, 1, 0, 0])

    def test_set_range_out_of_bounds_raises_and_leaves_unchanged(self):
        m = Mutibs.from_zeros(4)
        with pytest.raises(IndexError):
            m.set(range(2, 8))
        assert m == Mutibs.from_zeros(4)
        with pytest.raises(IndexError):
            m.set(range(-5, 2))
        assert m == Mutibs.from_zeros(4)
        with pytest.raises(IndexError):
            m.set(range(6, 2, -1))
        assert m == Mutibs.from_zeros(4)


class TestBugHuntFailing:
    """Failing tests for bugs found by inspection and differential fuzzing.
    """

    # --- Bug 1: in-place shifts used to panic when n > len -----------------
    #
    # Mutibs.__ilshift__ / __irshift__ passed the shift amount straight to
    # bitvec's shift_start / shift_end, which panic when the shift is larger
    # than the bit length. The non-inplace  <<  and  >>  operators clamp this
    # case and return all zeros, and the in-place versions must match rather
    # than let a pyo3_runtime.PanicException (a BaseException!) escape.

    def test_ilshift_larger_than_length_matches_lshift(self):
        # Tibs('0b10110') << 100 == Tibs.from_zeros(5), so <<= must match.
        m = Mutibs('0b10110')
        m <<= 100
        assert m == Mutibs.from_zeros(5)

    def test_irshift_larger_than_length_matches_rshift(self):
        m = Mutibs('0b10110')
        m >>= 100
        assert m == Mutibs.from_zeros(5)

    def test_ilshift_one_past_length(self):
        # Smallest formerly-panicking amount: len + 1. (n == len zero-fills.)
        m = Mutibs('0b1')
        m <<= 2
        assert m == Mutibs('0b0')

    # --- Bug 2: find_all_iter used to panic with byte_aligned + bounded end
    #
    # In the forward FindAllIterator, after yielding a byte-aligned match at
    # pos the state becomes current_pos = pos + 8, which may exceed the
    # requested `end`. The next __next__ call only guarded current_pos
    # against the haystack length, then called the search helper with
    # start > end, which panicked slicing the haystack (e.g. "range 8..4 out
    # of bounds: 20"). find_all with identical arguments returns normally,
    # and the two must agree.

    def test_find_all_iter_byte_aligned_bounded_end(self):
        t = Tibs.from_ones(20)
        expected = t.find_all('0b1', 0, 4, byte_aligned=True)
        assert expected == [0]
        # The 2nd next() used to panic with pyo3_runtime.PanicException.
        assert list(t.find_all_iter('0b1', 0, 4, byte_aligned=True)) == expected

    def test_find_all_iter_byte_aligned_match_near_end(self):
        # Match at a non-zero aligned position close to `end`.
        t = Tibs.from_zeros(8) + '0b1' + Tibs.from_zeros(11)
        expected = t.find_all('0b1', 0, 12, byte_aligned=True)
        assert expected == [8]
        assert list(t.find_all_iter('0b1', 0, 12, byte_aligned=True)) == expected

    def test_find_all_iter_byte_aligned_agrees_with_find_all(self):
        # Regression sweep over small bounded windows; every (start, end)
        # combination must agree with find_all instead of panicking.
        t = Tibs('0xb2a3cb8e6265d8ee0')
        needle = '0b0'
        for start in range(0, len(t), 7):
            for end in range(start, len(t), 5):
                expected = t.find_all(needle, start, end, byte_aligned=True)
                got = list(t.find_all_iter(needle, start, end, byte_aligned=True))
                assert got == expected, f"start={start} end={end}"

    # --- Bug 3: position arguments rejected documented Iterable inputs -----
    #
    # tibs.pyi declares pos as `SupportsIndex | Iterable[SupportsIndex]` (or
    # `| range`) for set/unset/set_at/unset_at and invert/inverted, and the
    # docstrings say "an iterable of bit positions". Generators, iterators
    # and sets are Iterables, and other APIs (split_at, from_bools,
    # from_joined) accept them, but these methods used to raise TypeError
    # because the implementation only extracted from sequences.

    def test_mutibs_set_accepts_generator(self):
        m = Mutibs.from_zeros(4)
        m.set(i for i in [1, 2])
        assert m == Mutibs('0b0110')

    def test_mutibs_unset_accepts_iterator(self):
        m = Mutibs.from_ones(4)
        m.unset(iter([0, 3]))
        assert m == Mutibs('0b0110')

    def test_tibs_set_at_accepts_generator(self):
        t = Tibs.from_zeros(4)
        assert t.set_at(i for i in [1, 2]) == Tibs('0b0110')

    def test_tibs_unset_at_accepts_set(self):
        t = Tibs.from_ones(4)
        assert t.unset_at({0, 3}) == Tibs('0b0110')

    def test_mutibs_invert_accepts_generator(self):
        m = Mutibs('0b0000')
        m.invert(i for i in [0, 2])
        assert m == Mutibs('0b1010')

    def test_tibs_inverted_accepts_iterator(self):
        assert Tibs('0b0000').inverted(iter([0, 2])) == Tibs('0b1010')

    # --- Behaviour intentionally preserved by the fixes --------------------

    def test_ishift_on_empty_mutibs_still_raises(self):
        # Matches Tibs() << 1, which also raises ValueError.
        m = Mutibs()
        with pytest.raises(ValueError):
            m <<= 1
        with pytest.raises(ValueError):
            m >>= 1

    def test_set_non_iterable_still_raises_type_error(self):
        m = Mutibs('0b00')
        with pytest.raises(TypeError):
            m.set(1.5)
        with pytest.raises(TypeError):
            m.invert(1.5)

    def test_set_generator_with_bad_index_is_atomic(self):
        # All positions are validated before any bit is written, matching
        # the existing behaviour for lists and ranges.
        m = Mutibs.from_zeros(4)
        with pytest.raises(IndexError):
            m.set(i for i in [1, 9])
        assert m == Mutibs.from_zeros(4)

    def test_set_generator_exception_propagates(self):
        def positions():
            yield 0
            raise ZeroDivisionError

        m = Mutibs('0b00')
        with pytest.raises(ZeroDivisionError):
            m.set(positions())
